// Assíncrono: publica um evento e segue
@Service
class PedidoService {
    private final KafkaTemplate<String, PedidoCriado> kafka;

    void finalizar(Pedido pedido) {
        repository.save(pedido);
        kafka.send("pedidos.criados", pedido.id().toString(), PedidoCriado.from(pedido));
    }
}

@Service
public class ProdutoService {
    @Cacheable(value = "produtos", key = "#id")
    public ProdutoResponse buscar(Long id) {
        return ProdutoResponse.from(repository.findById(id).orElseThrow());
    }

    @CacheEvict(value = "produtos", key = "#id")
    public void atualizarPreco(Long id, BigDecimal preco) {
        repository.atualizarPreco(id, preco);
    }
}
